# Gives the selected people a grade from a from-date together, in list order; responds with how many changed, and the people.
grade:
  class: net.officefloor.hq.app.person.BulkGradePeople
  govern: [ transaction ]
# Validate before load so a bad date is a 400, not masked by a 404. Responds with the sheet's people.
validate:
  class: net.officefloor.hq.app.person.ValidateRetire
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: retire
retire:
  class: net.officefloor.hq.app.person.RetirePerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import java.util.List;

/** How many people the bulk grade changed, and everyone on the sheet after it. */
public record BulkGradeResponse(int graded, List<Person> people) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Gives each selected person, in list order (by position), the grade from the from-date exactly as
 * the person form would, each with its own PERSON_EDITED and rollup lines. A bad grade or date, or a selected
 * person not on the sheet, refuses the whole action before anything is written. A viewer grades no one: it reports 0
 * and writes nothing.
 */
public class BulkGradePeople {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void grade(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @RequestBody BulkGradeRequest request, People people, SheetClock clock, Audit audit, Rollup rollup, Roles roles,
            ObjectResponse<BulkGradeResponse> response)
            throws InvalidPersonException, DuplicatePersonNameException, StalePersonException {
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("Grade must be A, B or C");
        }
        String from = request.from() == null ? "" : request.from().trim();
        if (!from.isEmpty()) {
            try {
                from = LocalDate.parse(from).toString();
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a valid from-date: " + from);
            }
        }
        Set<Long> selected = new HashSet<>(request.people() == null ? List.of() : request.people());
        List<Person> everyone = people.list(sheet);
        List<Person> chosen = everyone.stream().filter((p) -> selected.contains(p.id())).toList();
        if (chosen.size() != selected.size()) {
            throw new InvalidPersonException("Every selected person must be on the sheet");
        }
        if (Role.VIEWER.equals(roles.of(sheet, user))) {
            response.send(new BulkGradeResponse(0, everyone));
            return;
        }
        for (Person person : chosen) {
            // Re-read so each is saved as the store holds it after the ones before it.
            Person current = people.find(sheet, person.id());
            SavePerson.apply(sheet, user, current,
                    new PersonRequest(current.name(), grade, null, from.isEmpty() ? null : from,
                            current.terms() == null ? "" : current.terms().toString(),
                            current.contact() == null ? "" : current.contact()),
                    people, clock, audit, rollup);
        }
        response.send(new BulkGradeResponse(chosen.size(), people.list(sheet)));
    }
}
package net.officefloor.hq.app.person;

import java.util.List;

/** Body of POST /api/sheets/{sheet}/people/bulk-grade: the ids of the selected people, the grade, and its from-date (blank for the sheet's today). */
public record BulkGradeRequest(List<Long> people, String grade, String from) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** The date to retire from: the one given, or the sheet's today when blank. */
public class ValidateRetire {
    public void validate(@PathVariable("sheet") String sheet, @RequestBody RetireRequest request, SheetClock clock,
            Out<LocalDate> from) throws InvalidPersonException {
        String date = request == null || request.from() == null ? "" : request.from().trim();
        try {
            from.set(date.isEmpty() ? clock.today(sheet) : LocalDate.parse(date));
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("Not a valid date: " + date);
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Retires the person from the date: they count as retired at once; from the day the sheet's today reaches the date,
 * their OPEN and PENDING claims, unless bound by a statement, count in no live total.
 */
public class RetirePerson {
    public void retire(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
            @Val LocalDate from, People people, Audit audit, Rollup rollup) {
        Rollup.Snapshot before = rollup.take(sheet);
        people.retire(sheet, person.id(), from);
        audit.record("PERSON_RETIRED sheet=" + sheet + " by=" + user + " name=" + person.name() + " from=" + from);
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.person;

/** Body of POST /api/sheets/{sheet}/people/{person}/retire: the date retired from (blank for the sheet's today). */
public record RetireRequest(String from) {
}

